import{C as r,o as i,c as o,a2 as t,E as s}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"Delivery Route and Implementation Plan","description":"Hearth delivery master plan: seven capability stages, 35 vertical increments, 140 work packages, and exit evidence for each stage.","frontmatter":{"title":"Delivery Route and Implementation Plan","description":"Hearth delivery master plan: seven capability stages, 35 vertical increments, 140 work packages, and exit evidence for each stage.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/index.md","filePath":"en/delivery/index.md","lastUpdated":1793784691000}'),l={name:"en/delivery/index.md"},u=Object.assign(l,{setup(d){const a=[{no:"S0",meta:"4 increments",title:"Definition and Prototype",text:"Product wedge, real tasks, clickable prototype, protocol contracts, and evaluation baseline.",link:"/en/delivery/stage-0"},{no:"S1",meta:"6 increments",title:"Durable Kernel and MVP",text:"Walking skeleton, first Codex slice, MVP-1, side-effect safety, and recovery.",link:"/en/delivery/stage-1"},{no:"S2",meta:"6 increments",title:"Personal Operator",text:"Connectors, documents and data, web research, and writes that require approval.",link:"/en/delivery/stage-2"},{no:"S3",meta:"4 increments",title:"Computer Operator",text:"Desktop agentd, GUI observation, human takeover, and risk-tiered desktop actions.",link:"/en/delivery/stage-3"},{no:"S4",meta:"5 increments",title:"Proactive Personal Agent",text:"Triggers, proactive inbox, mobile PWA, and attention budgets.",link:"/en/delivery/stage-4"},{no:"S5",meta:"4 increments",title:"Memory and Evolution",text:"Memory Core, forgetting and export, skill candidates, evaluation, and rollback.",link:"/en/delivery/stage-5"},{no:"S6",meta:"6 increments",title:"Multi-device and Long-running",text:"Event sync, offline queues, device revocation, backup, migration, and operations.",link:"/en/delivery/stage-6"}];return(c,e)=>{const n=r("DocCardGrid");return i(),o("div",null,[e[0]||(e[0]=t('<p class="eyebrow">DELIVERY</p><h1 id="delivery-route-and-implementation-plan" tabindex="-1">Delivery Route and Implementation Plan <a class="header-anchor" href="#delivery-route-and-implementation-plan" aria-label="Permalink to &quot;Delivery Route and Implementation Plan&quot;">​</a></h1><p class="lead">There is one master plan: Stages 0–6 define capability gates, 35 D increments define the construction order, and each increment contains four work packages. The route promises no dates, only visible product outcomes, verification evidence, and recovery paths at every stage.</p><h2 id="guiding-principles" tabindex="-1">Guiding Principles <a class="header-anchor" href="#guiding-principles" aria-label="Permalink to &quot;Guiding Principles&quot;">​</a></h2><ul><li><strong>Stage is a capability gate, not a schedule.</strong> You can stay, trial, and roll back, but cannot skip recovery, interface, verification, or safety boundaries.</li><li><strong>Every increment is a vertical slice.</strong> User outcome, interface, persistent state, real execution, verification, and recovery arrive together.</li><li><strong>Ship an MVP early.</strong> MVP-1 is an early exit from Stage 1, not a demo produced at the end of the project.</li><li><strong>Narrow before broad.</strong> Make one task family dependable before expanding connectors, desktop, proactivity, and multi-device support.</li><li><strong>Safety before side effects.</strong> Sending, writing, sharing, deleting, and desktop actions require authorization, idempotency, and receipts first.</li><li><strong>Evidence before announcements.</strong> A stage is complete only when real tasks, failure recovery, and evaluations prove it.</li></ul><h2 id="seven-stages" tabindex="-1">Seven Stages <a class="header-anchor" href="#seven-stages" aria-label="Permalink to &quot;Seven Stages&quot;">​</a></h2>',6)),s(n,{items:a,columns:2}),e[1]||(e[1]=t('<h2 id="stage-overview" tabindex="-1">Stage Overview <a class="header-anchor" href="#stage-overview" aria-label="Permalink to &quot;Stage Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>What the User Gets</th><th>What Must Be Proven Before Moving On</th></tr></thead><tbody><tr><td>Stage 0</td><td>A clickable end-to-end prototype</td><td>Product wedge, 12 real tasks, stable contracts, evaluation and approval baselines</td></tr><tr><td>Stage 1</td><td>A locally usable personal task workbench</td><td>Persistent state, real Codex execution, approvals, artifacts, recovery, and MVP-1</td></tr><tr><td>Stage 2</td><td>A Personal Operator for daily content work</td><td>Connector loops, source citations, document/data verification, approved writes, and receipts</td></tr><tr><td>Stage 3</td><td>A Computer Operator for desktop work</td><td>GUI observation, human takeover, isolation, desktop verification, and high-risk approvals</td></tr><tr><td>Stage 4</td><td>A low-interruption proactive personal agent</td><td>Triggers, attention budgets, mobile approvals, pause, and device revocation</td></tr><tr><td>Stage 5</td><td>An agent that accumulates context and improves safely</td><td>Correctable/forgettable/exportable memory and evaluated, promoted, rollback-capable skills</td></tr><tr><td>Stage 6</td><td>A multi-device, portable, long-running Personal Agent OS</td><td>Sync consistency, offline recovery, device revocation, migration, and operations evidence</td></tr></tbody></table><p>Each stage page defines its scope and exit conditions in detail. Stages advance by capability dependency, not by calendar boundaries.</p><h2 id="_35-increments-140-work-packages" tabindex="-1">35 Increments, 140 Work Packages <a class="header-anchor" href="#_35-increments-140-work-packages" aria-label="Permalink to &quot;35 Increments, 140 Work Packages&quot;">​</a></h2><p>Every D increment follows the same delivery template so progress cannot hide behind backend-only work:</p><table tabindex="0"><thead><tr><th>Deliverable</th><th>Required Answer</th></tr></thead><tbody><tr><td>User-visible outcome</td><td>What concrete thing can the user now do in the browser?</td></tr><tr><td>Implementation landing</td><td>Which modules, interfaces, events, and tests must be completed?</td></tr><tr><td>Acceptance rehearsal</td><td>What repeatable steps prove that it really works?</td></tr><tr><td>Failure and recovery</td><td>What does the user see on failure, and how can they cancel, retry, take over, or undo?</td></tr></tbody></table><p>Each increment contains four implementation work packages. Work can be split, but completing one package never substitutes for accepting the whole increment.</p><h2 id="where-the-mvp-sits" tabindex="-1">Where the MVP Sits <a class="header-anchor" href="#where-the-mvp-sits" aria-label="Permalink to &quot;Where the MVP Sits&quot;">​</a></h2><p>MVP-1 is D1.3 in Stage 1: a truly usable local personal task workbench. It must include Web task cards, persistent task state, real Codex execution, artifacts, an approval rehearsal, and failure recovery, but not email, calendar, GUI, proactive loops, or multi-device support.</p><h2 id="six-execution-rules" tabindex="-1">Six Execution Rules <a class="header-anchor" href="#six-execution-rules" aria-label="Permalink to &quot;Six Execution Rules&quot;">​</a></h2><ol><li><strong>Vertical slices first.</strong> Do not deliver a “partial stage” made only of CLI, logs, database, or APIs.</li><li><strong>The frontend grows at the same time.</strong> Stage 0 has a prototype, Stage 1 has real Web task cards, and every later increment has a user path.</li><li><strong>Durability before autonomy.</strong> Tasks cannot disappear, side effects cannot duplicate, and failures must be visible.</li><li><strong>Safety before real side effects.</strong> High-risk actions require preview, authorization, idempotency, and receipts.</li><li><strong>Evaluation before expansion.</strong> Every new executor, connector, model, and skill needs representative tasks, baselines, and failure samples.</li><li><strong>Cut scope, never foundations.</strong> Reduce coverage and autonomy before reducing interface, state, recovery, audit, and revocation.</li></ol><h2 id="engineering-constraints" tabindex="-1">Engineering Constraints <a class="header-anchor" href="#engineering-constraints" aria-label="Permalink to &quot;Engineering Constraints&quot;">​</a></h2><p>Every stage must also meet engineering baselines for contract and integration tests, fault injection, security tests, performance and long-running stability, observability, backup/export, and rollback-capable releases. Detailed repository layout, testing, risks, and decisions live in the appendix:</p><ul><li><a href="/hearth-os/en/reference/engineering.html">Engineering and Repository Structure</a></li><li><a href="/hearth-os/en/reference/risks.html">Risks and Kill Criteria</a></li><li><a href="/hearth-os/en/reference/decisions.html">ADRs and Key Decisions</a></li></ul><h2 id="start-here" tabindex="-1">Start Here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start Here&quot;">​</a></h2><p>Read <a href="/hearth-os/en/design/">Design &amp; Tradeoffs</a> to understand why Hearth is designed this way, then begin at <a href="/hearth-os/en/delivery/stage-0.html">Stage 0</a>. If the current stage is already clear, use the sidebar to open the relevant stage and D increment.</p>',16))])}}});export{h as __pageData,u as default};
